package br.org.rosalina.social.student;
import br.org.rosalina.social.catalog.CatalogItem; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="student_relative") public class StudentRelative {
 @Id @GeneratedValue private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) private Student student; @Enumerated(EnumType.STRING) @Column(nullable=false) private RelativeType type; private String kinship; @Column(nullable=false) private String name; @Column(name="birth_date") private LocalDate birthDate; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="occupation_id") private CatalogItem occupation; private Boolean literate; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="education_id") private CatalogItem education; private String phone,rg,cpf; @Column(name="voter_registration") private String voterRegistration;
 public RelativeType getType(){return type;} public String getKinship(){return kinship;} public String getName(){return name;} public LocalDate getBirthDate(){return birthDate;} public CatalogItem getOccupation(){return occupation;} public Boolean getLiterate(){return literate;} public CatalogItem getEducation(){return education;} public String getPhone(){return phone;} public String getRg(){return rg;} public String getCpf(){return cpf;} public String getVoterRegistration(){return voterRegistration;}
 public void setStudent(Student v){student=v;} public void setType(RelativeType v){type=v;} public void setKinship(String v){kinship=v;} public void setName(String v){name=v;} public void setBirthDate(LocalDate v){birthDate=v;} public void setOccupation(CatalogItem v){occupation=v;} public void setLiterate(Boolean v){literate=v;} public void setEducation(CatalogItem v){education=v;} public void setPhone(String v){phone=v;} public void setRg(String v){rg=v;} public void setCpf(String v){cpf=v;} public void setVoterRegistration(String v){voterRegistration=v;}
}
